def _compile_code(code_str, name, env=None, verbose=False):
    if env is None:
        env = {}
    try:
        code = compile(code_str, '<cli_spec>', 'exec')
        exec(code, env)
    except Exception as e:
        if verbose:
            raise
        raise UsageError(f'could not compile spec, got: {e.__class__.__name__}: {e}')
    return env[name]
